INSERT INTO `achievements` (`id`, `name`, `description`, `icon`, `condition`, `expReward`) VALUES (1,'初出茅庐','发布第一个辩论案件','📝','发布 1 个案件',50),(2,'案件达人','累计发布 5 个辩论案件','📋','发布 5 个案件',100),(3,'辩论狂人','累计发布 20 个辩论案件','🔥','发布 20 个案件',200),(4,'初试牛刀','第一次参与投票','🗳','投票 1 次',30),(5,'决策达人','累计投票 10 次','⚖','投票 10 次',80),(6,'慧眼识珠','投票命中率超过 60%','👁','投票命中率 >= 60%',150),(7,'倾听者','完成 10 次 AI 共情对话','💚','完成 10 次共情会话',100),(8,'知识贡献者','上传第一份知识库文档','📚','上传 1 份知识库文档',80),(9,'智能体创造者','创建第一个自建智能体','🤖','创建 1 个自建智能体',120),(10,'社交达人','粉丝数超过 10','🌟','粉丝数 >= 10',200),(11,'人气爆棚','累计围观量超过 500','🎉','总围观量 >= 500',150),(12,'老朋友','注册满 30 天','🎂','注册满 30 天',100),(13,'辩论达人','发布 5 个辩论案件','🎤','发布 5 个案件',100),(14,'人气辩手','获得 100 次围观','👁','累计 100 围观',80),(15,'观点领袖','获得 10 次投票支持','🏆','获得 10 票',120),(16,'第一票','参与第一次投票','🗳️','投票 1 次',30),(17,'积极参与者','参与 10 次投票','⚡','投票 10 次',60),(18,'知心朋友','关注第一位用户','👥','关注 1 人',20),(19,'收藏家','收藏 5 个案件','⭐','收藏 5 个案件',40),(20,'热心评论员','发表 10 条评论','💬','评论 10 次',50),(21,'情绪探索者','完成第一次情绪辅导','💚','完成 1 次辅导',60);
