  `senderId` int unsigned DEFAULT NULL,
  `botId` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `content` longtext COLLATE utf8mb4_unicode_ci NOT NULL,
  `reasoning` longtext COLLATE utf8mb4_unicode_ci,
  `roundNumber` int unsigned DEFAULT NULL,
  `parentId` int unsigned DEFAULT NULL,
  `createdAt` datetime(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  PRIMARY KEY (`id`),
  KEY `messages_roomId_idx` (`roomId`),
  KEY `messages_senderId_idx` (`senderId`),
