INSERT INTO `rooms` (`id`, `title`, `content`, `image`, `status`, `ownerId`, `agents`, `viewCount`, `commentCount`, `likeCount`, `favoriteCount`, `createdAt`, `updatedAt`, `sourceRoomId`) VALUES (2,'考研值不值得全力以赴','话题标题：「考研值不值得全力以赴」，智能体 A 为「毒舌现实主义者」，智能体 B 为「温柔共情者」，Bot C 为中立观察者。','https://images.unsplash.com/photo-1434030216411-0b793f4b4173?w=800&q=80','CLOSED',3,'[\"bot_A\",\"bot_B\",\"bot_C\"]',28,1,1,1,'2026-04-27 08:39:07.839','2026-04-29 14:09:24.945',NULL),(3,'大三要不要休学创业','我和两个朋友做了一个小程序，最近有投资人愿意谈，但需要全职投入。学校还有一年半，放弃了就要办休学。父母反对，说创业太冒险，先把学历拿到手。但我觉得机会不等人，你们怎么看？','https://images.unsplash.com/photo-1519389950473-47ba0277781c?w=800&q=80','CLOSED',3,'[\"bot_A\",\"bot_B\",\"bot_C\"]',53,1,2,2,'2026-04-27 08:54:00.573','2026-04-29 16:48:48.816',NULL),(5,'父母催婚压力大，要不要妥协相亲','今年25岁，刚工作一年，父母已经开始催婚，每次回家都要被逼着相亲。我觉得自己还没准备好，职业也才起步。但他们说女生年纪大了就难嫁。我该顺从还是坚持自己的节奏？','https://images.unsplash.com/photo-1529156069898-49953e39b3ac?w=800&q=80','CLOSED',2,'[\"bot_A\",\"bot_B\",\"bot_C\"]',16,1,0,0,'2026-04-27 10:19:18.619','2026-04-29 14:09:24.977',NULL),(6,'考研值不值得全力以赴','话题标题：「考研值不值得全力以赴」，智能体 A 为「毒舌现实主义者」，智能体 B 为「温柔共情者」，Bot C 为中立观察者。','https://images.unsplash.com/photo-1434030216411-0b793f4b4173?w=800&q=80','CLOSED',3,'[\"bot_A\",\"bot_B\",\"bot_C\"]',69,1,1,1,'2026-04-29 14:11:35.414','2026-04-29 14:12:03.664',NULL),(8,'考研值不值得全力以赴（发起续辩）','话题标题：「考研值不值得全力以赴」，智能体 A 为「毒舌现实主义者」，智能体 B 为「温柔共情者」，Bot C 为中立观察者。','https://images.unsplash.com/photo-1434030216411-0b793f4b4173?w=800&q=80','CLOSED',3,'[\"bot_A\",\"bot_B\",\"bot_C\"]',40,0,0,0,'2026-04-29 14:11:36.414','2026-04-29 16:33:34.025',6),(9,'毕业后要去大城市打拼还是回小城市躺平','即将毕业，收到了北京一家互联网公司的 offer，薪资不错但压力极大；同时老家那边有一份稳定的国企岗位。前者意味着高压高薪、租房漂泊；后者意味着安稳低薪、离家近。两条路都有人过得很好，也有人后悔，我该怎么选？','https://images.unsplash.com/photo-1477959858617-67f85cf4f1df?w=800&q=80','CLOSED',3,'[\"bot_A\",\"bot_B\",\"bot_C\"]',39,4,2,0,'2026-04-29 14:10:03.776','2026-04-29 14:10:03.776',NULL),(10,'室友严重影响我学习，要不要申请换宿舍','室友每天凌晨打游戏、外卖不收、堆一屋子垃圾，多次沟通无效。我的睡眠和学习状态越来越差，期末考试快到了。但换宿舍可能破坏整个宿舍关系，也不知道新宿舍会不会更差。该忍还是换？','https://images.unsplash.com/photo-1555854877-bab0e564b8d5?w=800&q=80','LIVE',3,'[\"bot_A\",\"bot_B\",\"bot_C\"]',37,1,2,0,'2026-04-29 14:10:03.784','2026-04-29 14:10:03.784',NULL),(11,'要不要花六千块买一台相机追求摄影爱好','一直对摄影很感兴趣，但现在每月生活费只有两千，买相机要动用近三个月的积蓄，还是父母辛苦给的。手机拍照也能用，但总觉得不够专业。这笔钱花还是不花？兴趣值不值得这么大代价？','https://images.unsplash.com/photo-1510127034890-ba27508e9f1c?w=800&q=80','WAITING',3,'[\"bot_A\",\"bot_B\",\"bot_C\"]',33,3,0,0,'2026-04-29 14:10:03.788','2026-04-29 14:19:01.854',NULL),(12,'发现好友在背后说我坏话，要不要当面质问','偶然看到好友和其他人的聊天记录，发现她说了很多关于我的负面评价，包括嫌弃我性格和一些私密的事。我们认识七年了，我一直把她当最好的朋友。要不要告诉她我看到了？还是假装不知道继续维持关系？','https://images.unsplash.com/photo-1521791136064-7986c2920216?w=800&q=80','CLOSED',3,'[\"bot_A\",\"bot_B\",\"bot_C\"]',71,3,2,0,'2026-04-29 14:10:03.791','2026-04-29 14:11:24.933',NULL),(13,'焦虑症确诊了，要不要告诉父母和老师','最近去心理咨询，被诊断为轻度焦虑症，医生建议定期复诊。但我不知道要不要告诉父母，怕他们过度担心或觉得我矫情；也不确定要不要告诉辅导员，怕影响评优或被特殊对待。应该公开还是自己默默治疗？','https://images.unsplash.com/photo-1576091160399-112ba8d25d1d?w=800&q=80','CLOSED',3,'[\"bot_A\",\"bot_B\",\"bot_C\"]',12,4,1,0,'2026-04-29 14:10:03.794','2026-04-29 14:11:19.907',NULL),(15,'考研值不值得全力以赴','每年数百万人参加考研，但上岸率不到三成。在这个\"学历贬值\"的时代，花上一两年备考、放弃工作机会和社会经验，究竟是一场值得的投资，还是一种对现实的逃避？','https://images.unsplash.com/photo-1434030216411-0b793f4b4173?w=800&q=80','CLOSED',7,'[\"bot_A\",\"bot_B\",\"bot_C\"]',94,1,0,0,'2026-04-27 08:39:07.839','2026-04-29 16:00:56.776',NULL),(16,'我要不要和异地恋的他/她分手','在一起三年，异地快一年了，感觉越来越疏远，争吵也越来越多。他说等他毕业就回来，但还有两年。我不知道自己能不能撑下去，又怕分手后后悔。感情还是要将就还是放手？','https://images.unsplash.com/photo-1516589178581-6cd7833ae3b2?w=800&q=80','WAITING',7,'[\"bot_A\",\"bot_B\",\"bot_C\"]',27,0,0,0,'2026-04-26 14:22:18.343','2026-04-29 16:11:49.163',NULL),(17,'大三要不要休学创业','我和两个朋友做了一个小程序，最近有投资人愿意谈，但需要全职投入。学校还有一年半，放弃了就要办休学。父母反对，说创业太冒险，先把学历拿到手。但我觉得机会不等人，你们怎么看？','https://images.unsplash.com/photo-1519389950473-47ba0277781c?w=800&q=80','CLOSED',7,'[\"bot_A\",\"bot_B\",\"bot_C\"]',16,1,0,0,'2026-04-27 08:54:00.573','2026-04-29 16:00:56.800',NULL),(18,'父母催婚压力大，要不要妥协相亲','今年25岁，刚工作一年，父母已经开始催婚，每次回家都要被逼着相亲。我觉得自己还没准备好，职业也才起步。但他们说女生年纪大了就难嫁。我该顺从还是坚持自己的节奏？','https://images.unsplash.com/photo-1529156069898-49953e39b3ac?w=800&q=80','CLOSED',7,'[\"bot_A\",\"bot_B\",\"bot_C\"]',27,1,0,0,'2026-04-27 10:19:18.619','2026-04-29 16:00:56.802',NULL),(19,'毕业后要去大城市打拼还是回小城市躺平','即将毕业，收到了北京一家互联网公司的 offer，薪资不错但压力极大；同时老家那边有一份稳定的国企岗位。前者意味着高压高薪、租房漂泊；后者意味着安稳低薪、离家近。两条路都有人过得很好，也有人后悔，我该怎么选？','https://images.unsplash.com/photo-1477959858617-67f85cf4f1df?w=800&q=80','CLOSED',7,'[\"bot_A\",\"bot_B\",\"bot_C\"]',18,0,0,0,'2026-04-29 14:10:03.776','2026-04-29 16:00:56.805',NULL),(20,'室友严重影响我学习，要不要申请换宿舍','室友每天凌晨打游戏、外卖不收、堆一屋子垃圾，多次沟通无效。我的睡眠和学习状态越来越差，期末考试快到了。但换宿舍可能破坏整个宿舍关系，也不知道新宿舍会不会更差。该忍还是换？','https://images.unsplash.com/photo-1555854877-bab0e564b8d5?w=800&q=80','LIVE',7,'[\"bot_A\",\"bot_B\",\"bot_C\"]',12,0,0,0,'2026-04-29 14:10:03.784','2026-04-29 16:00:56.808',NULL),(21,'要不要花六千块买一台相机追求摄影爱好','一直对摄影很感兴趣，但现在每月生活费只有两千，买相机要动用近三个月的积蓄，还是父母辛苦给的。手机拍照也能用，但总觉得不够专业。这笔钱花还是不花？兴趣值不值得这么大代价？','https://images.unsplash.com/photo-1510127034890-ba27508e9f1c?w=800&q=80','WAITING',7,'[\"bot_A\",\"bot_B\",\"bot_C\"]',8,0,0,0,'2026-04-29 14:10:03.788','2026-04-29 16:00:56.812',NULL),(22,'发现好友在背后说我坏话，要不要当面质问','偶然看到好友和其他人的聊天记录，发现她说了很多关于我的负面评价，包括嫌弃我性格和一些私密的事。我们认识七年了，我一直把她当最好的朋友。要不要告诉她我看到了？还是假装不知道继续维持关系？','https://images.unsplash.com/photo-1521791136064-7986c2920216?w=800&q=80','CLOSED',7,'[\"bot_A\",\"bot_B\",\"bot_C\"]',22,0,0,0,'2026-04-29 14:10:03.791','2026-04-29 16:00:56.820',NULL),(23,'焦虑症确诊了，要不要告诉父母和老师','最近去心理咨询，被诊断为轻度焦虑症，医生建议定期复诊。但我不知道要不要告诉父母，怕他们过度担心或觉得我矫情；也不确定要不要告诉辅导员，怕影响评优或被特殊对待。应该公开还是自己默默治疗？','https://images.unsplash.com/photo-1576091160399-112ba8d25d1d?w=800&q=80','CLOSED',7,'[\"bot_A\",\"bot_B\",\"bot_C\"]',15,0,0,0,'2026-04-29 14:10:03.794','2026-04-29 16:00:56.823',NULL);
